INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_041_M1_S4', 'hydrostatics', '4', 'hydrostatics: Analysis of fluids at rest, including pressure distributions, forces on submerged surfaces, buoyancy, and related equilibrium conditions. In Fluid Properties and Flow Fundamentals, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_041_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M1_S5', 'pressure measurement', '5', 'pressure measurement refers to the methods and principles used to obtain and interpret measurements of pressure measurement under specified conditions. In Fluid Properties and Flow Fundamentals, the focus is on the analysis, design, implementation, interpretation, or evaluation of pressure measurement within Fluid Flow and Heat Transfer, particularly where the Fluid Properties and Flow Fundamentals module establishes its technical context.', 'SSD_COURSE_041_M1_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M2_S1', 'laminar flow', '1', 'laminar flow: Flow regime characterized by relatively ordered fluid motion with limited cross-stream mixing and viscous forces dominating over inertial effects at sufficiently low Reynolds number. In Internal Flow, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_041_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M2_S2', 'turbulent flow', '2', 'turbulent flow: Flow regime characterized by irregular, three-dimensional fluctuations and enhanced mixing, typically associated with sufficiently high Reynolds number and strong inertial effects. In Internal Flow, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_041_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M2_S3', 'friction factor', '3', 'friction factor refers to a dimensionless factor used to represent wall-friction losses in internal pipe flow. In Internal Flow, the focus is on the analysis, design, implementation, interpretation, or evaluation of friction factor within Fluid Flow and Heat Transfer, particularly where the Internal Flow module establishes its technical context.', 'SSD_COURSE_041_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M2_S4', 'pipe fittings', '4', 'pipe fittings: Components such as bends, valves, tees, and reducers that change flow direction or area and cause local losses. In Internal Flow, the focus is on the analysis, design, implementation, interpretation, or evaluation of pipe fittings within Fluid Flow and Heat Transfer, particularly where the Internal Flow module establishes its technical context.', 'SSD_COURSE_041_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M2_S5', 'pumping requirements', '5', 'pumping requirements refers to the flow rate and head or pressure increase that a pump must provide for a specified hydraulic system. In Internal Flow, the focus is on the analysis, design, implementation, interpretation, or evaluation of pumping requirements within Fluid Flow and Heat Transfer, particularly where the Internal Flow module establishes its technical context.', 'SSD_COURSE_041_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M3_S1', 'drag', '1', 'drag: Fluid force acting opposite to the relative motion of a body through a fluid. In External Flow and Boundary Layers, the focus is on the analysis, design, implementation, interpretation, or evaluation of drag within Fluid Flow and Heat Transfer, particularly where the External Flow and Boundary Layers module establishes its technical context.', 'SSD_COURSE_041_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M3_S2', 'boundary layers', '2', 'boundary layers: Thin regions adjacent to solid surfaces in which viscous effects produce strong velocity gradients and influence momentum, heat, or mass transfer. In External Flow and Boundary Layers, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_041_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M3_S3', 'flow separation', '3', 'flow separation: Detachment of a boundary layer from a surface when an adverse pressure gradient causes near-wall flow to reverse or weaken. In External Flow and Boundary Layers, the focus is on the analysis, design, implementation, interpretation, or evaluation of flow separation within Fluid Flow and Heat Transfer, particularly where the External Flow and Boundary Layers module establishes its technical context.', 'SSD_COURSE_041_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M3_S4', 'pressure drop', '4', 'pressure drop refers to the reduction in fluid pressure along equipment or piping caused by friction, fittings, elevation, or other flow resistance. In External Flow and Boundary Layers, the focus is on the analysis, design, implementation, interpretation, or evaluation of pressure drop within Fluid Flow and Heat Transfer, particularly where the External Flow and Boundary Layers module establishes its technical context.', 'SSD_COURSE_041_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M4_S1', 'momentum balance', '1', 'momentum balance refers to an application of conservation of momentum to relate forces, pressure, and momentum changes in a fluid system. In Momentum Transport and Dimensional Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of momentum balance within Fluid Flow and Heat Transfer, particularly where the Momentum Transport and Dimensional Analysis module establishes its technical context.', 'SSD_COURSE_041_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M4_S2', 'dimensional groups', '2', 'dimensional groups: Dimensionless combinations of variables, such as Reynolds or Nusselt number, used to characterise transport behaviour. In Momentum Transport and Dimensional Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of dimensional groups within Fluid Flow and Heat Transfer, particularly where the Momentum Transport and Dimensional Analysis module establishes its technical context.', 'SSD_COURSE_041_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M4_S3', 'similitude', '3', 'similitude: Conditions under which a model and full-scale system have sufficiently similar governing dimensionless parameters to represent the same behaviour. In Momentum Transport and Dimensional Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of similitude within Fluid Flow and Heat Transfer, particularly where the Momentum Transport and Dimensional Analysis module establishes its technical context.', 'SSD_COURSE_041_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M4_S4', 'scale-up', '4', 'scale-up: Translation of process or equipment behaviour from a smaller reference scale to a larger scale while accounting for geometric, transport, kinetic, and operating constraints. In Momentum Transport and Dimensional Analysis, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_041_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M5_S1', 'Fourier law', '1', 'Fourier law: Fourier law in Fluid Flow and Heat Transfer concerns legal rules, institutional mechanisms, duties, procedures, and compliance considerations governing fourier law. In Heat Conduction and Convection, the focus is on the analysis, design, implementation, interpretation, or evaluation of Fourier law within Fluid Flow and Heat Transfer, particularly where the Heat Conduction and Convection module establishes its technical context.', 'SSD_COURSE_041_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M5_S2', 'steady conduction', '2', 'steady conduction: Heat conduction in which temperature at each location does not change with time. In Heat Conduction and Convection, the focus is on the analysis, design, implementation, interpretation, or evaluation of steady conduction within Fluid Flow and Heat Transfer, particularly where the Heat Conduction and Convection module establishes its technical context.', 'SSD_COURSE_041_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M5_S3', 'transient conduction', '3', 'transient conduction: Heat conduction in which temperature varies with time as well as position. In Heat Conduction and Convection, the focus is on the analysis, design, implementation, interpretation, or evaluation of transient conduction within Fluid Flow and Heat Transfer, particularly where the Heat Conduction and Convection module establishes its technical context.', 'SSD_COURSE_041_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M5_S4', 'natural and forced convection', '4', 'natural and forced convection: Heat transfer by fluid motion driven respectively by buoyancy or by an external device such as a fan or pump. In Heat Conduction and Convection, the focus is on the analysis, design, implementation, interpretation, or evaluation of natural and forced convection within Fluid Flow and Heat Transfer, particularly where the Heat Conduction and Convection module establishes its technical context.', 'SSD_COURSE_041_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M6_S1', 'Log Mean Temperature Difference (LMTD)', '1', 'LMTD: Log-mean temperature difference, a mean temperature-driving-force measure used in heat-exchanger analysis when the temperature difference varies along the exchanger. In Heat Exchangers, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_041_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M6_S2', 'effectiveness-NTU', '2', 'effectiveness-NTU refers to a heat-exchanger analysis method based on effectiveness and the number of transfer units. In Heat Exchangers, the focus is on the analysis, design, implementation, interpretation, or evaluation of effectiveness-NTU within Fluid Flow and Heat Transfer, particularly where the Heat Exchangers module establishes its technical context.', 'SSD_COURSE_041_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M6_S3', 'exchanger configurations', '3', 'exchanger configurations: Arrangements of heat-exchanger flow paths and surfaces, such as parallel flow, counterflow, crossflow, shell-and-tube, or plate configurations. In Heat Exchangers, the focus is on the analysis, design, implementation, interpretation, or evaluation of exchanger configurations within Fluid Flow and Heat Transfer, particularly where the Heat Exchangers module establishes its technical context.', 'SSD_COURSE_041_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M6_S4', 'fouling', '4', 'fouling: Accumulation of unwanted deposits on heat-transfer surfaces that increases thermal resistance and may reduce performance. In Heat Exchangers, the focus is on the analysis, design, implementation, interpretation, or evaluation of fouling within Fluid Flow and Heat Transfer, particularly where the Heat Exchangers module establishes its technical context.', 'SSD_COURSE_041_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M6_S5', 'design', '5', 'design refers to the structured process of defining requirements, constraints, alternatives, and implementation decisions for design. In Heat Exchangers, the focus is on the analysis, design, implementation, interpretation, or evaluation of design within Fluid Flow and Heat Transfer, particularly where the Heat Exchangers module establishes its technical context.', 'SSD_COURSE_041_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M7_S1', 'thermal radiation', '1', 'thermal radiation: Heat transfer by electromagnetic emission between surfaces without requiring a material medium. In Radiation and Thermal Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of thermal radiation within Fluid Flow and Heat Transfer, particularly where the Radiation and Thermal Systems module establishes its technical context.', 'SSD_COURSE_041_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M7_S2', 'emissivity', '2', 'emissivity refers to a surface property describing its thermal-radiation emission relative to an ideal blackbody. In Radiation and Thermal Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of emissivity within Fluid Flow and Heat Transfer, particularly where the Radiation and Thermal Systems module establishes its technical context.', 'SSD_COURSE_041_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M7_S3', 'view factors', '3', 'view factors: Geometric factors representing the fraction of radiation leaving one surface that directly reaches another. In Radiation and Thermal Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of view factors within Fluid Flow and Heat Transfer, particularly where the Radiation and Thermal Systems module establishes its technical context.', 'SSD_COURSE_041_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M7_S4', 'combined modes', '4', 'combined modes: Heat-transfer situations involving two or more mechanisms such as conduction, convection, and radiation. In Radiation and Thermal Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of combined modes within Fluid Flow and Heat Transfer, particularly where the Radiation and Thermal Systems module establishes its technical context.', 'SSD_COURSE_041_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_041_M7_S5', 'insulation', '5', 'insulation: Material or construction used to reduce unwanted heat transfer by increasing thermal resistance. In Radiation and Thermal Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of insulation within Fluid Flow and Heat Transfer, particularly where the Radiation and Thermal Systems module establishes its technical context.', 'SSD_COURSE_041_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M1_S1', 'Fick law', '1', 'Fick law: Fick law in Mass Transfer Operations concerns legal rules, institutional mechanisms, duties, procedures, and compliance considerations governing fick law. In Diffusion and Mass-Transfer Fundamentals, the focus is on the analysis, design, implementation, interpretation, or evaluation of Fick law within Mass Transfer Operations, particularly where the Diffusion and Mass-Transfer Fundamentals module establishes its technical context.', 'SSD_COURSE_042_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M1_S2', 'molecular diffusion', '2', 'molecular diffusion: Mass transport caused by molecular motion down a concentration or chemical-potential gradient. In Diffusion and Mass-Transfer Fundamentals, the focus is on the analysis, design, implementation, interpretation, or evaluation of molecular diffusion within Mass Transfer Operations, particularly where the Diffusion and Mass-Transfer Fundamentals module establishes its technical context.', 'SSD_COURSE_042_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M1_S3', 'mass-transfer coefficients', '3', 'mass-transfer coefficients: Parameters relating mass-transfer flux to a driving-force difference between a bulk phase and an interface. In Diffusion and Mass-Transfer Fundamentals, the focus is on the analysis, design, implementation, interpretation, or evaluation of mass-transfer coefficients within Mass Transfer Operations, particularly where the Diffusion and Mass-Transfer Fundamentals module establishes its technical context.', 'SSD_COURSE_042_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M1_S4', 'interfacial transport', '4', 'interfacial transport: Mass transfer across the boundary between two contacting phases. In Diffusion and Mass-Transfer Fundamentals, the focus is on the analysis, design, implementation, interpretation, or evaluation of interfacial transport within Mass Transfer Operations, particularly where the Diffusion and Mass-Transfer Fundamentals module establishes its technical context.', 'SSD_COURSE_042_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M2_S1', 'equilibrium relations', '1', 'equilibrium relations: Relationships defining the compositions or concentrations of phases when they are at equilibrium. In Gas Absorption and Stripping, the focus is on the analysis, design, implementation, interpretation, or evaluation of equilibrium relations within Mass Transfer Operations, particularly where the Gas Absorption and Stripping module establishes its technical context.', 'SSD_COURSE_042_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M2_S2', 'operating lines', '2', 'operating lines: Relationships between phase flow rates and compositions used to analyse staged or continuous separation processes. In Gas Absorption and Stripping, the focus is on the analysis, design, implementation, interpretation, or evaluation of operating lines within Mass Transfer Operations, particularly where the Gas Absorption and Stripping module establishes its technical context.', 'SSD_COURSE_042_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M2_S3', 'Height of a Transfer Unit / Number of Transfer Units (HTU/NTU)', '3', 'HTU/NTU: Height and number-of-transfer-unit methods used to design packed mass-transfer equipment. In Gas Absorption and Stripping, the focus is on the analysis, design, implementation, interpretation, or evaluation of HTU/NTU within Mass Transfer Operations, particularly where the Gas Absorption and Stripping module establishes its technical context.', 'SSD_COURSE_042_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M2_S4', 'packed columns', '4', 'packed columns: Mass-transfer columns containing packing that provides contact area between flowing phases. In Gas Absorption and Stripping, the focus is on the analysis, design, implementation, interpretation, or evaluation of packed columns within Mass Transfer Operations, particularly where the Gas Absorption and Stripping module establishes its technical context.', 'SSD_COURSE_042_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M3_S1', 'vapour-liquid equilibrium', '1', 'vapour-liquid equilibrium refers to the equilibrium relationship between vapour and liquid compositions at specified temperature or pressure. In Distillation, the focus is on the analysis, design, implementation, interpretation, or evaluation of vapour-liquid equilibrium within Mass Transfer Operations, particularly where the Distillation module establishes its technical context.', 'SSD_COURSE_042_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M3_S2', 'McCabe-Thiele', '2', 'McCabe-Thiele refers to a graphical method for analysing binary distillation using equilibrium and operating lines. In Distillation, the focus is on the analysis, design, implementation, interpretation, or evaluation of McCabe-Thiele within Mass Transfer Operations, particularly where the Distillation module establishes its technical context.', 'SSD_COURSE_042_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M3_S3', 'reflux', '3', 'reflux: Liquid returned to a distillation column from condensed overhead vapour to improve separation. In Distillation, the focus is on the analysis, design, implementation, interpretation, or evaluation of reflux within Mass Transfer Operations, particularly where the Distillation module establishes its technical context.', 'SSD_COURSE_042_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M3_S4', 'tray efficiency', '4', 'tray efficiency refers to a measure of how closely an actual tray approaches the mass-transfer performance of an ideal equilibrium stage. In Distillation, the focus is on the analysis, design, implementation, interpretation, or evaluation of tray efficiency within Mass Transfer Operations, particularly where the Distillation module establishes its technical context.', 'SSD_COURSE_042_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M3_S5', 'multicomponent concepts', '5', 'multicomponent concepts: Methods for analysing separation of mixtures containing more than two components. In Distillation, the focus is on the analysis, design, implementation, interpretation, or evaluation of multicomponent concepts within Mass Transfer Operations, particularly where the Distillation module establishes its technical context.', 'SSD_COURSE_042_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M4_S1', 'distribution coefficients', '1', 'distribution coefficients: Ratios describing how a solute partitions between two phases at equilibrium. In Liquid-Liquid Extraction, the focus is on the analysis, design, implementation, interpretation, or evaluation of distribution coefficients within Mass Transfer Operations, particularly where the Liquid-Liquid Extraction module establishes its technical context.', 'SSD_COURSE_042_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M4_S2', 'ternary diagrams', '2', 'ternary diagrams: Triangular composition diagrams used to represent equilibrium and separation behaviour of three-component mixtures. In Liquid-Liquid Extraction, the focus is on the analysis, design, implementation, interpretation, or evaluation of ternary diagrams within Mass Transfer Operations, particularly where the Liquid-Liquid Extraction module establishes its technical context.', 'SSD_COURSE_042_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M4_S3', 'stagewise extraction', '3', 'stagewise extraction: Liquid-liquid extraction analysis in which contacting is represented by discrete equilibrium or mass-transfer stages. In Liquid-Liquid Extraction, the focus is on the analysis, design, implementation, interpretation, or evaluation of stagewise extraction within Mass Transfer Operations, particularly where the Liquid-Liquid Extraction module establishes its technical context.', 'SSD_COURSE_042_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M4_S4', 'solvent selection', '4', 'solvent selection refers to the process of choosing among alternatives for solvent selection using defined performance, service, design, and constraint criteria. In Liquid-Liquid Extraction, the focus is on the analysis, design, implementation, interpretation, or evaluation of solvent selection within Mass Transfer Operations, particularly where the Liquid-Liquid Extraction module establishes its technical context.', 'SSD_COURSE_042_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M5_S1', 'psychrometrics', '1', 'psychrometrics: psychrometrics in Mass Transfer Operations concerns the analysis of moist-air properties and processes using quantities such as dry-bulb temperature, humidity ratio, relative humidity, enthalpy, and dew point. In Humidification and Drying, the focus is on the analysis, design, implementation, interpretation, or evaluation of psychrometrics within Mass Transfer Operations, particularly where the Humidification and Drying module establishes its technical context.', 'SSD_COURSE_042_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M5_S2', 'wet-bulb temperature', '2', 'wet-bulb temperature refers to the temperature indicated by a wetted sensor exposed to moving air, reflecting evaporative cooling under specified conditions. In Humidification and Drying, the focus is on the analysis, design, implementation, interpretation, or evaluation of wet-bulb temperature within Mass Transfer Operations, particularly where the Humidification and Drying module establishes its technical context.', 'SSD_COURSE_042_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M5_S3', 'drying curves', '3', 'drying curves: Plots describing the rate or extent of moisture removal from a wet solid during drying. In Humidification and Drying, the focus is on the analysis, design, implementation, interpretation, or evaluation of drying curves within Mass Transfer Operations, particularly where the Humidification and Drying module establishes its technical context.', 'SSD_COURSE_042_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M5_S4', 'drying-rate periods', '4', 'drying-rate periods: Distinct stages of drying, commonly including constant-rate and falling-rate periods. In Humidification and Drying, the focus is on the analysis, design, implementation, interpretation, or evaluation of drying-rate periods within Mass Transfer Operations, particularly where the Humidification and Drying module establishes its technical context.', 'SSD_COURSE_042_M5_S4', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;